import numpy as np

def run(inputs: dict) -> dict:
    metrics = inputs.get("ExtractedMetric", [])
    if not metrics:
        raise ValueError("Нет данных ExtractedMetric")

    target_concepts = {"SALES_REVENUE", "Выручка"}
    target_unit = "млн. руб."

    values = []
    for m in metrics:
        concept = m.get("concept")
        if concept not in target_concepts:
            continue
        sf = m.get("scalar_fact")
        if not sf:
            continue
        unit = sf.get("unit")
        if unit != target_unit:
            raise ValueError(f"Несовместимая единица: {unit}, ожидалась {target_unit}")
        values.append(sf["value"])

    if len(values) < 2:
        raise ValueError("Недостаточно периодов для расчёта CV (нужно минимум 2)")

    arr = np.array(values, dtype=np.float64)
    mean = float(np.mean(arr))
    std_dev = float(np.std(arr, ddof=0))  # популяционное СКО, как в классическом CV
    if mean == 0:
        raise ValueError("Среднее значение равно нулю, CV не определён")
    cv = (std_dev / mean) * 100.0

    return {"cv": cv, "mean": mean, "std_dev": std_dev}
